const ctx = $('Obtener contexto del cliente').first().json;
const input = $('Entrada (tool: escalar_a_nairobi)').first().json;
const msgs = $input.all().map(i => i.json).reverse();

const summary = `ESCALACIÓN · urgencia ${input.urgency.toUpperCase()}\n` +
  `Cliente: ${ctx.name || 'sin nombre registrado'} · ${ctx.phone} (${ctx.customer_status || 'sin estado'})\n` +
  `Motivo: ${input.reason}\n` +
  (ctx.last_policy_number ? `Póliza: ${ctx.last_policy_number} — ${ctx.last_insurer_name}\n` : 'Sin póliza activa registrada\n') +
  (ctx.balance_due > 0 ? `Saldo pendiente: ${ctx.balance_due}\n` : '') +
  (ctx.open_claim_id ? `Tiene un siniestro abierto (id ${ctx.open_claim_id})\n` : '') +
  `Contexto: ${input.context_summary || 'sin detalle adicional'}\n` +
  `Últimos mensajes:\n` + msgs.map(m => `  [${m.direction}] ${m.body || ''}`).join('\n');

return [{ json: { ...ctx, ...input, summary } }];

