insert into public.escalations (conversation_id, contact_id, reason, urgency, context, summary)
values ($1, $2, $3, $4, $5::jsonb, $6)
returning id;

select ($2 = 'emergency') or (
  extract(hour from now() at time zone coalesce((select value #>> '{}' from public.settings where key='timezone'),'America/Caracas'))
  between (select (value #>> '{}')::int from public.settings where key='business_hours_start')
      and (select (value #>> '{}')::int from public.settings where key='business_hours_end')
) as notify_now,
(select value #>> '{}' from public.settings where key='emergency_contact_phone') as nairobi_chat_id;
